<?php
declare(strict_types=1);
function render_admin_page(string $page): void {require_admin();switch($page){case 'team':view_team();break;case 'approvals':view_approvals();break;case 'settings':view_settings();break;case 'backup':view_backup();break;case 'audit':view_audit();break;default:fail('Seite nicht gefunden.');}}
function view_team(): void {
 $edit=isset($_GET['edit'])?one('users','id=?',[(int)$_GET['edit']]):null;echo '<details class="card editor"'.($edit?' open':'').'><summary>'.($edit?'Mitarbeiter bearbeiten':'+ Mitarbeiter anlegen').'</summary>';form_start('user_save',['id'=>$edit['id']??0]);echo '<div class="form-grid">';field('Name','name',$edit['name']??'','text','required');field('E-Mail / Anmeldename','email',$edit['email']??'','email','required');field('Personalnummer','personnel',$edit['personnel']??'');select_field('Rolle','role',['employee'=>'Mitarbeiter','admin'=>'Administrator'],$edit['role']??'employee');field('Beschäftigungsbeginn','employment_start',$edit['employment_start']??today(),'date','required');field('Beschäftigungsende (optional)','employment_end',$edit['employment_end']??'','date');field('Jährlicher Urlaubsanspruch','vacation_days',$edit['vacation_days']??'','number','min="0" max="366" step="0.5" '.($edit?'readonly':''));field($edit?'Neues vorläufiges Passwort (leer = unverändert)':'Vorläufiges Passwort','password','','password','minlength="12" maxlength="72" '.($edit?'':'required'));echo '</div><label class="checkbox"><input type="checkbox" name="active" '.(!$edit||$edit['active']?'checked':'').'> Konto aktiv</label>';if($edit)textarea('Begründung der Änderung','reason','',true);submit('Mitarbeiter speichern');echo '</details><section class="card"><h2>Ihr Team</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>E-Mail</th><th>Rolle</th><th>Status</th><th>Aktionen</th></tr></thead><tbody>';foreach(rows('users','1',[],'ORDER BY active DESC,name') as $u)echo '<tr><td><strong>'.h($u['name']).'</strong><small>'.h($u['personnel']).'</small></td><td>'.h($u['email']).'</td><td>'.($u['role']==='admin'?'Administrator':'Mitarbeiter').'</td><td>'.($u['active']?'Aktiv':'Inaktiv').'</td><td><a href="index.php?page=team&edit='.$u['id'].'">Bearbeiten</a> · <a href="index.php?page=times&user='.$u['id'].'">Zeiten</a> · <a href="index.php?page=documents&user='.$u['id'].'">Dokumente</a></td></tr>';echo '</tbody></table></div></section>';
 if(!$edit)return;$uid=(int)$edit['id'];if($uid!==(int)user()['id']){echo '<details class="card"><summary>Mitarbeiter dauerhaft löschen</summary><p>Entfernt Konto, Zeiten, Abwesenheiten, Dokumente, Arbeitszeitmodelle, Korrekturen und zugehörige Protokolle. Auch vorhandene Sicherungsarchive auf diesem Server werden entfernt. Externe Backups und Exporte müssen Sie separat behandeln. Wenn Daten noch aufbewahrt werden müssen, deaktivieren Sie das Konto stattdessen.</p>';form_start('user_delete',['id'=>$uid]);field('Zur Bestätigung MITARBEITER LÖSCHEN eingeben','confirm','','text','required autocomplete="off"');field('Ihr Administratorpasswort','admin_password','','password','required autocomplete="current-password"');textarea('Begründung (ohne Namen oder andere personenbezogene Angaben)','reason','',true);echo '<label class="checkbox"><input type="checkbox" name="retention_checked" value="1" required> Aufbewahrungspflichten geprüft; die Daten dürfen gelöscht werden.</label>';submit('Mitarbeiter und Daten endgültig löschen','danger');echo '</details>';}echo '<section class="card"><h2>Arbeitszeitmodelle · '.h($edit['name']).'</h2><p class="muted">Neue Konten starten ohne Sollstunden. Sollstunden werden erst durch ein ausdrücklich hinterlegtes Arbeitszeitmodell festgelegt. Neue Modelle gelten ab dem gewählten Datum. Rückwirkende Änderungen gesperrter Monate erfordern deren Wiederöffnung.</p><div class="table-wrap"><table><tr><th>Gültig ab</th><th>Mo</th><th>Di</th><th>Mi</th><th>Do</th><th>Fr</th><th>Sa</th><th>So</th></tr>';foreach(rows('models','user_id=?',[$uid],'ORDER BY valid_from DESC') as $m){echo '<tr><td>'.h($m['valid_from']).'</td>';foreach(json_decode($m['minutes'],true) as $v)echo '<td>'.hours((int)$v).'</td>';echo '</tr>';}echo '</table></div>';form_start('model_save',['user_id'=>$uid]);field('Gültig ab','valid_from',today(),'date','required');echo '<div class="weekday-grid">';foreach(['Mo','Di','Mi','Do','Fr','Sa','So'] as $i=>$name)field($name.' · Stunden','hours['.$i.']',0,'number','min="0" max="24" step="0.25" required');echo '</div>';textarea('Begründung','reason','',true);submit('Arbeitszeitmodell hinterlegen');echo '</section><section class="card"><h2>Saldo- und Urlaubskorrektur</h2><p class="muted">Für Startsalden, Urlaubsübertrag, anteiligen Jahresurlaub oder begründete Korrekturen. Urlaubsbuchungen gelten nur im Jahr des Buchungsdatums. Negative Werte ziehen Stunden oder Tage ab. Fehler durch eine Gegenbuchung korrigieren.</p>';form_start('adjustment',['user_id'=>$uid]);echo '<div class="form-grid">';field('Buchungsdatum','day',today(),'date','required');field('Stunden (+/−)','hours',0,'number','step="0.25"');field('Urlaubstage (+/−)','vacation',0,'number','step="0.5"');echo '</div>';textarea('Begründung','reason','',true);submit('Korrektur buchen');foreach(rows('adjustments','user_id=?',[$uid],'ORDER BY day DESC') as $a)echo '<div class="notice">'.h($a['day']).' · '.hours((int)$a['minutes']).' Stunden · '.h($a['vacation']).' Urlaubstage<small>'.h($a['reason']).'</small></div>';echo '</section>';
}
function view_approvals(): void {
 echo '<section class="card"><h2>Offene Abwesenheitsanträge</h2>';$list=rows('absences',"status='pending'",[],'ORDER BY created_at');if(!$list)empty_state('Alles bearbeitet','Keine offenen Abwesenheitsanträge.');foreach($list as $a){$u=one('users','id=?',[$a['user_id']]);echo '<div class="document-row"><div><h3>'.h($u['name']).'</h3>'.badge($a['type']).'<p>'.h($a['start_date']).' – '.h($a['end_date']).' · '.((int)($a['amount_minutes']??0)>0?hours((int)$a['amount_minutes']).' Std. pro Tag':($a['fraction']==0.5?'halbtags':'ganztags')).'</p><p>'.h($a['note']).'</p></div>';form_start('absence_review',['id'=>$a['id']]);select_field('Entscheidung','status',['approved'=>'Freigeben','rejected'=>'Ablehnen']);textarea('Begründung / Rückmeldung (optional)','reason');submit('Entscheidung speichern');echo '</div>';}echo '</section><section class="card"><h2>Monate zur Prüfung</h2>';$list=rows('closures',"status='submitted'",[],'ORDER BY month,user_id');if(!$list)empty_state('Keine offenen Monatsabschlüsse','Eingereichte Monatszettel erscheinen hier.');foreach($list as $c){$u=one('users','id=?',[$c['user_id']]);echo '<div class="entry-row"><div><h3>'.h($u['name']).'</h3><p>'.h($c['month']).'</p></div><a class="button secondary" href="index.php?page=reports&user='.$u['id'].'&month='.h($c['month']).'">Monat prüfen</a></div>';}echo '</section><section class="card"><h2>Abwesenheiten im Team</h2><div class="table-wrap"><table><tr><th>Mitarbeiter</th><th>Zeitraum</th><th>Art</th><th>Status</th></tr>';foreach(rows('absences','end_date>=?',[(new DateTimeImmutable(today()))->modify('-30 days')->format('Y-m-d')],'ORDER BY start_date LIMIT 200') as $a){$u=one('users','id=?',[$a['user_id']]);echo '<tr><td><a href="index.php?page=absences&user='.$a['user_id'].'&month='.substr($a['start_date'],0,7).'">'.h($u['name']).'</a></td><td>'.h($a['start_date']).' – '.h($a['end_date']).'</td><td>'.badge($a['type']).'</td><td>'.badge($a['status']).'</td></tr>';}echo '</table></div></section>';
}
function view_settings(): void {
 echo '<section class="card"><h2>Unternehmen & Erscheinungsbild</h2><p class="muted">Diese Angaben erscheinen auf der Anmeldung und in Ihren Berichten. IT-Janz bleibt als Entwickler getrennt gekennzeichnet.</p>';form_start('settings',[],true);echo '<div class="form-grid">';foreach(['company'=>'Unternehmensname','contact'=>'Ansprechpartner','email'=>'E-Mail','phone'=>'Telefon','website'=>'Website (HTTPS)','imprint'=>'Link zum Impressum (HTTPS)','privacy'=>'Link zum Datenschutz (HTTPS)','location'=>'Standort','state'=>'Bundesland'] as $k=>$label)field($label,$k,setting($k),$k==='email'?'email':'text',$k==='company'?'required':'');field('Akzentfarbe','color',setting('color','#117a82'),'color');field('Zeitzone','timezone',setting('timezone','Europe/Berlin'));field('Firmenlogo (PNG/JPG)','company_logo','','file','accept="image/png,image/jpeg"');echo '</div>';textarea('Anschrift','address',setting('address'));field('Bezeichnung der sonstigen Abwesenheit','other_absence_label',setting('other_absence_label','Sonstige Abwesenheit'));select_field('Anrechnung sonstiger Abwesenheit','other_absence_paid',['1'=>'Als Sollzeit gutschreiben','0'=>'Keine Zeitgutschrift'],setting('other_absence_paid','1'));echo '<h3>Prüfhinweise und Dokumente</h3><p class="muted">Diese Regeln erzeugen Hinweise und verändern keine erfassten Zeiten. Rechtliche und betriebliche Vorgaben müssen individuell geprüft werden.</p><div class="form-grid">';foreach(['max_daily'=>['Hinweis ab täglichen Arbeitsminuten',600],'pause_short'=>['Pausenhinweis nach mehr als 6 Stunden (Minuten)',30],'pause_long'=>['Pausenhinweis nach mehr als 9 Stunden (Minuten)',45],'rest_hours'=>['Ruhezeithinweis unter (Stunden)',11],'upload_mb'=>['Maximale Uploadgröße (MB, 1–50)',10],'retention_days'=>['Dokument-Aufbewahrung (Tage, 0 = keine Löschfreigabe)',0]] as $k=>[$label,$default])field($label,$k,setting($k,(string)$default),'number','min="0" required');echo '</div>';submit('Unternehmensangaben speichern');echo '</section><section class="card"><h2>Feiertage</h2><p class="muted">Feiertage für Ihren Standort manuell eintragen. Das Bundesland ist eine Standortangabe; Feiertage werden nicht automatisch aus dem Internet übernommen.</p>';form_start('holiday_save');echo '<div class="form-grid">';field('Datum','day',today(),'date','required');field('Bezeichnung','name','','text','required');field('Begründung','reason','Feiertagskalender pflegen','text','required');echo '</div>';submit('Feiertag speichern');foreach(rows('holidays','1',[],'ORDER BY day DESC LIMIT 200') as $d){echo '<div class="entry-row"><span>'.h($d['day']).' · '.h($d['name']).'</span>';form_start('holiday_delete',['id'=>$d['id'],'reason'=>'Feiertag entfernt']);submit('Entfernen','text-button');echo '</div>';}echo '</section><section class="card"><h2>Aufbewahrung ausführen</h2><p>Entfernt ausschließlich erledigte oder zurückgewiesene Dokumente, die älter als die konfigurierte Frist sind. Vorher Aufbewahrungspflichten prüfen und Backup erstellen.</p>';form_start('retention_cleanup');field('Begründung / Freigabe','reason','','text','required');submit('Alte abgeschlossene Dokumente löschen','danger');echo '</section>';
}
function view_backup(): void {
 echo '<p class="muted">Installierte Version: MaStunden '.h(APP_VERSION).'</p>';
 $j=job();echo '<section class="card"><h2>Daten sicher aufbewahren</h2><p>Backups enthalten Datenbank, Unterlagen und Logos. Sie werden mit Ihrem Backup-Passwort AES-verschlüsselt. Datenbankzugangsdaten bleiben in der lokalen config.php und werden nicht exportiert.</p><p class="muted">Während des Vorgangs bleibt die Anwendung für Änderungen gesperrt. Dieses Fenster geöffnet lassen; die Verarbeitung erfolgt in kleinen Schritten. Temporäre fertige Archive werden bei einem späteren Administratoraufruf nach 24 Stunden entfernt.</p>';
 if($j){echo '<div class="alert">'.($j['mode']==='backup'?'Sicherung':'Wiederherstellung').' · Phase: '.h($j['phase']).' · Schritt '.(int)($j['index']??($j['table']+$j['file_index'])).'</div>';if(!empty($j['safety']))echo '<p><a class="button secondary" href="index.php?backup_download='.h($j['safety']).'">Sicherheitsbackup herunterladen</a></p>';
 if($j['phase']==='ready'){echo '<p>Archiv und Prüfsummen sind geprüft. Die wiederhergestellten Daten liegen bereit. Laden Sie das Sicherheitsbackup herunter, bevor Sie die bestehenden Tabellen ersetzen. Danach werden alle Benutzer abgemeldet.</p>';form_start('restore_commit');field('Zur Bestätigung DATEN ERSETZEN eingeben','confirm','','text','required');submit('Wiederherstellung abschließen','danger');}
 elseif(in_array($j['phase'],['switching','switched'],true)){form_start('backup_cancel');submit('Unterbrochenen Abschluss bereinigen');}
 else{echo '<div id="job-step">';form_start($j['mode']==='backup'?'backup_step':'restore_step');submit('Nächsten Schritt ausführen');echo '</div><p class="muted">Der nächste Schritt startet automatisch. Bei einer Fehlermeldung erfolgt kein automatischer Neustart.</p>';}
 if(!in_array($j['phase'],['switching','switched'],true)){form_start('backup_cancel');submit('Vorgang abbrechen','text-button');}echo '</section>';return;
 }
 if(isset($_SESSION['latest_backup'])&&is_file(storage_path($_SESSION['latest_backup'])))echo '<p><a class="button" href="index.php?backup_download='.h($_SESSION['latest_backup']).'">Letztes Backup herunterladen</a></p>';
 form_start('backup_start');field('Neues Backup-Passwort (12–72 Zeichen)','backup_password','','password','required minlength="12" maxlength="72"');submit('Vollständiges Backup erstellen');echo '</section><section class="card"><h2>Backup wiederherstellen</h2><p>Vor jeder Wiederherstellung wird automatisch ein verschlüsseltes Sicherheitsbackup des aktuellen Bestands erstellt. Die vorhandenen Daten werden erst nach Prüfung und einer zweiten Bestätigung ersetzt. Verwenden Sie ausschließlich eigene, vertrauenswürdige MaStunden-Backups derselben Version.</p><p class="muted">PHP-Uploadlimit: '.h(ini_get('upload_max_filesize')).', Anfragegröße: '.h(ini_get('post_max_size')).'. Für größere Archive oder einen Serverumzug siehe Installationsanleitung.</p>';form_start('restore_upload',[],true);field('MaStunden-Backup (ZIP)','archive','','file','accept=".zip"');echo '<label class="checkbox"><input type="checkbox" name="use_ftp"> Statt Upload: incoming-backup.zip aus dem privaten FTP-Ordner verwenden</label>';field('Passwort des hochgeladenen Backups','archive_password','','password','required');field('Neues Passwort für das Sicherheitsbackup','backup_password','','password','required minlength="12"');field('Zur Bestätigung WIEDERHERSTELLEN eingeben','confirm','','text','required');submit('Backup prüfen und Wiederherstellung vorbereiten','danger');echo '</section>';
}
function view_audit(): void {
 $page=max(1,(int)($_GET['p']??1));$list=q('SELECT * FROM '.table('audit').' ORDER BY id DESC LIMIT 50 OFFSET '.(($page-1)*50))->fetchAll();echo '<section class="card"><p class="muted">Änderungsnachweis mit Vorher-/Nachherwerten. Dokumentinhalte und Passwörter werden nicht protokolliert. Das Protokoll ist über diese Oberfläche nicht veränderbar; es ist keine extern zertifizierte revisionssichere Archivierung.</p>';foreach($list as $a){$u=$a['actor_id']?one('users','id=?',[$a['actor_id']]):null;echo '<article class="audit-entry"><p><strong>Begründung:</strong> '.h($a['reason']!==''?$a['reason']:'Keine Begründung hinterlegt.').'</p><details><summary>'.h(local_time($a['created_at'])).' · '.h($u['name']??'System').' · '.h(['delete'=>'Gelöscht','cancel'=>'Zurückgezogen / storniert','employee_erased'=>'Mitarbeiterdaten gelöscht','review'=>'Entscheidung','save'=>'Gespeichert'][$a['action']]??$a['action']).' / '.h($a['entity']).' #'.h($a['entity_id']).'</summary><p>'.h($a['reason']).'</p><div class="form-grid"><pre>'.h(json_encode(json_decode($a['before_json']??'null'),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre><pre>'.h(json_encode(json_decode($a['after_json']??'null'),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre></div></details></article>';}echo '<div class="button-row">';if($page>1)echo '<a class="button secondary" href="index.php?page=audit&p='.($page-1).'">Zurück</a>';if(count($list)===50)echo '<a class="button secondary" href="index.php?page=audit&p='.($page+1).'">Weitere Einträge</a>';echo '</div></section>';
}
